                $valid = false;
                $message = 'Este cupom já foi utilizado anteriormente por esta conta.';
            }
        }

        if ($valid) {
            set_alert('success', 'Cupom aplicado com sucesso!');
            // Aqui você pode redirecionar para o checkout ou recalcular o carrinho
